const ASSETS={"index.html":"","styles.css":"","auth.css":"","app.js":"","auth.js":""};
const encoder=new TextEncoder();
const headers={"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store"};
const response=(body,status=200,extra={})=>new Response(JSON.stringify(body),{status,headers:{...headers,...extra}});
const bad=(message,status=400)=>response({error:message},status);
function b64(bytes){let s="";for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/=/g,"").replace(/\+/g,"-").replace(/\//g,"_")}
function unb64(s){s=s.replace(/-/g,"+").replace(/_/g,"/");while(s.length%4)s+="=";return Uint8Array.from(atob(s),c=>c.charCodeAt(0))}
function secretBytes(value){return encoder.encode(value||"")}
async function hmacKey(secret){return crypto.subtle.importKey("raw",secretBytes(secret),{name:"HMAC",hash:"SHA-256"},false,["sign","verify"])}
async function makeSession(account,secret){const payload=b64(encoder.encode(JSON.stringify({sub:account.id,exp:Date.now()+7*24*60*60*1000})));const signature=b64(new Uint8Array(await crypto.subtle.sign("HMAC",await hmacKey(secret),encoder.encode(payload))));return `${payload}.${signature}`}
async function sessionUser(request,env){const token=(request.headers.get("Cookie")||"").split(";").map(x=>x.trim()).find(x=>x.startsWith("tomly_session="))?.slice("tomly_session=".length);if(!token||!env.SESSION_SECRET)return null;const [payload,signature]=token.split(".");if(!payload||!signature)return null;try{const ok=await crypto.subtle.verify("HMAC",await hmacKey(env.SESSION_SECRET),unb64(signature),encoder.encode(payload));if(!ok)return null;const decoded=JSON.parse(new TextDecoder().decode(unb64(payload)));if(decoded.exp<Date.now())return null;return await env.DB.prepare("SELECT a.id,a.username,a.role,a.band_id,b.name AS band_name FROM accounts a LEFT JOIN bands b ON b.id=a.band_id WHERE a.id=?1").bind(decoded.sub).first()}catch{return null}}
function cookie(token,maxAge=604800){return `tomly_session=${token}; Path=/; HttpOnly; Secure; SameSite=Lax; Max-Age=${maxAge}`}
function randomHex(bytes=16){return Array.from(crypto.getRandomValues(new Uint8Array(bytes)),x=>x.toString(16).padStart(2,"0")).join("")}
async function passwordHash(password,salt){const key=await crypto.subtle.importKey("raw",encoder.encode(password),"PBKDF2",false,["deriveBits"]);const result=await crypto.subtle.deriveBits({name:"PBKDF2",salt:Uint8Array.from(salt.match(/.{2}/g),x=>parseInt(x,16)),iterations:100000,hash:"SHA-256"},key,256);return Array.from(new Uint8Array(result),x=>x.toString(16).padStart(2,"0")).join("")}
function sameSecret(a,b){a=String(a||"");b=String(b||"");let diff=a.length^b.length;for(let i=0;i<Math.max(a.length,b.length);i++)diff|=(a.charCodeAt(i)||0)^(b.charCodeAt(i)||0);return diff===0}
async function readBody(request){const length=Number(request.headers.get("content-length")||0);if(length>1_500_000)throw new Error("Os dados enviados excedem o limite de 1,5 MB.");return request.json()}
function validPassword(password,min=8){return typeof password==="string"&&password.length>=min&&password.length<=128}
function bandDefaults(){return JSON.stringify({folders:["Adoração","Celebração","Cantor Cristão"],songs:[],scales:[],sets:[]})}
async function api(request,env,url){
  const origin=request.headers.get("Origin");if(origin&&origin!==url.origin)return bad("Origem não permitida.",403);
  const {pathname,searchParams}=url,method=request.method;
  try{
    if(pathname==="/api/me"&&method==="GET"){const admin=await env.DB.prepare("SELECT id FROM accounts WHERE role='admin' LIMIT 1").first();const user=await sessionUser(request,env);return response(user?{user:{id:user.id,username:user.username,role:user.role,bandId:user.band_id,bandName:user.band_name}}:{user:null,setupRequired:!admin})}
    if(pathname==="/api/setup"&&method==="POST"){const existing=await env.DB.prepare("SELECT id FROM accounts WHERE role='admin' LIMIT 1").first();if(existing)return bad("A configuração inicial já foi concluída.",409);if(!env.ADMIN_SETUP_TOKEN||!env.SESSION_SECRET)return bad("A configuração inicial do servidor está incompleta.",503);const body=await readBody(request);if(!sameSecret(body.token,env.ADMIN_SETUP_TOKEN))return bad("Código inicial inválido.",403);if(!validPassword(body.password,10))return bad("A senha precisa ter de 10 a 128 caracteres.");const salt=randomHex();const id=crypto.randomUUID();const hash=await passwordHash(body.password,salt);await env.DB.prepare("INSERT INTO accounts (id,username,role,band_id,salt,password_hash) VALUES (?1,'admin','admin',NULL,?2,?3)").bind(id,salt,hash).run();const token=await makeSession({id},env.SESSION_SECRET);return response({ok:true},200,{"Set-Cookie":cookie(token)})}
    if(pathname==="/api/login"&&method==="POST"){if(!env.SESSION_SECRET)return bad("A sessão do servidor não está configurada.",503);const body=await readBody(request);const username=String(body.username||"").trim();const password=String(body.password||"");if(username.length<1||username.length>80||password.length>128)return bad("Usuário ou senha inválidos.",401);const account=await env.DB.prepare("SELECT a.id,a.username,a.role,a.band_id,a.salt,a.password_hash,b.name AS band_name FROM accounts a LEFT JOIN bands b ON b.id=a.band_id WHERE a.username=?1").bind(username).first();if(!account||!sameSecret(await passwordHash(password,account.salt),account.password_hash))return bad("Usuário ou senha inválidos.",401);const token=await makeSession(account,env.SESSION_SECRET);return response({ok:true},200,{"Set-Cookie":cookie(token)})}
    if(pathname==="/api/logout"&&method==="POST")return response({ok:true},200,{"Set-Cookie":cookie("",0)});
    const user=await sessionUser(request,env);if(!user)return bad("Entre na sua banda para continuar.",401);
    if(pathname==="/api/bands"&&method==="GET"){if(user.role!=="admin")return bad("Apenas o administrador pode consultar as bandas.",403);const rows=await env.DB.prepare("SELECT id,name,created_at FROM bands ORDER BY name COLLATE NOCASE").all();return response({bands:rows.results||[]})}
    if(pathname==="/api/bands"&&method==="POST"){if(user.role!=="admin")return bad("Apenas o administrador pode cadastrar bandas.",403);const body=await readBody(request),name=String(body.name||"").trim(),password=String(body.password||"");if(name.length<2||name.length>80)return bad("O nome da banda precisa ter entre 2 e 80 caracteres.");if(name.toLowerCase()==="admin")return bad("Esse nome está reservado ao administrador.");if(!validPassword(password))return bad("A senha precisa ter de 8 a 128 caracteres.");const id=crypto.randomUUID(),salt=randomHex(),hash=await passwordHash(password,salt);try{await env.DB.batch([env.DB.prepare("INSERT INTO bands (id,name) VALUES (?1,?2)").bind(id,name),env.DB.prepare("INSERT INTO accounts (id,username,role,band_id,salt,password_hash) VALUES (?1,?2,'band',?1,?3,?4)").bind(id,name,salt,hash),env.DB.prepare("INSERT INTO band_data (band_id,data_json) VALUES (?1,?2)").bind(id,JSON.stringify(body.data&&typeof body.data==="object"?body.data:JSON.parse(bandDefaults())))]);return response({band:{id,name},ok:true},201)}catch{return bad("Já existe uma banda com esse nome.",409)}}
    const bandMatch=pathname.match(/^\/api\/bands\/([^/]+)(?:\/(password))?$/);if(bandMatch){if(user.role!=="admin")return bad("Apenas o administrador pode administrar bandas.",403);const bandId=decodeURIComponent(bandMatch[1]);if(bandMatch[2]==="password"&&method==="PUT"){const body=await readBody(request),password=String(body.password||"");if(!validPassword(password))return bad("A senha precisa ter de 8 a 128 caracteres.");const salt=randomHex(),hash=await passwordHash(password,salt),result=await env.DB.prepare("UPDATE accounts SET salt=?1,password_hash=?2 WHERE band_id=?3 AND role='band'").bind(salt,hash,bandId).run();return response({ok:true},result.meta?.changes?200:404)}if(method==="DELETE"){await env.DB.batch([env.DB.prepare("DELETE FROM band_data WHERE band_id=?1").bind(bandId),env.DB.prepare("DELETE FROM accounts WHERE band_id=?1").bind(bandId),env.DB.prepare("DELETE FROM bands WHERE id=?1").bind(bandId)]);return response({ok:true})}return bad("Operação não encontrada.",404)}
    if(pathname==="/api/data"&&(method==="GET"||method==="PUT")){let bandId=user.role==="admin"?String(searchParams.get("bandId")||""):user.band_id;if(!bandId)return bad("Selecione uma banda.",400);if(user.role!=="admin"&&bandId!==user.band_id)return bad("Você não tem acesso a essa banda.",403);const band=await env.DB.prepare("SELECT id FROM bands WHERE id=?1").bind(bandId).first();if(!band)return bad("Banda não encontrada.",404);if(method==="GET"){const row=await env.DB.prepare("SELECT data_json FROM band_data WHERE band_id=?1").bind(bandId).first();let data={};try{data=JSON.parse(row?.data_json||bandDefaults())}catch{}return response({data})}const body=await readBody(request);if(!body||typeof body!=="object"||Array.isArray(body))return bad("Formato de dados inválido.");const serialized=JSON.stringify(body);if(serialized.length>1_500_000)return bad("Os dados da banda excedem o limite de 1,5 MB.");await env.DB.prepare("INSERT INTO band_data (band_id,data_json,updated_at) VALUES (?1,?2,CURRENT_TIMESTAMP) ON CONFLICT(band_id) DO UPDATE SET data_json=excluded.data_json,updated_at=CURRENT_TIMESTAMP").bind(bandId,serialized).run();return response({ok:true})}
    return bad("Rota não encontrada.",404)
  }catch(error){return bad(error?.message||"Falha inesperada no servidor.",500)}
}
function textAsset(base64,type){const binary=atob(base64);const bytes=Uint8Array.from(binary,c=>c.charCodeAt(0));return new Response(new TextDecoder().decode(bytes),{headers:{"Content-Type":type,"Cache-Control":"no-cache"}})}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname.startsWith("/api/"))return api(request,env,url);const path=url.pathname==="/"||url.pathname==="/index.html"?"index.html":url.pathname.replace(/^\//,"");const type={"index.html":"text/html; charset=utf-8","styles.css":"text/css; charset=utf-8","auth.css":"text/css; charset=utf-8","app.js":"text/javascript; charset=utf-8","auth.js":"text/javascript; charset=utf-8"}[path];if(type&&ASSETS[path])return textAsset(ASSETS[path],type);return new Response("Not found",{status:404})}};
